reference_solution:
nums = [int(x) for x in input().split()]

candidate = None
count = 0
for x in nums:
    if count == 0:
        candidate = x
    count += 1 if x == candidate else -1

# second pass: the candidate must really be a majority
if nums.count(candidate) > len(nums) // 2:
    print(candidate)
else:
    print("NONE")

nums = sorted(int(x) for x in input().split())
n = len(nums)

found = False
for i in range(n - 2):
    if i > 0 and nums[i] == nums[i - 1]:
        continue                        # same first value: same triplets
    lo, hi = i + 1, n - 1
    while lo < hi:
        s = nums[i] + nums[lo] + nums[hi]
        if s < 0:
            lo += 1
        elif s > 0:
            hi -= 1
        else:
            print(nums[i], nums[lo], nums[hi])
            found = True
            lo += 1
            hi -= 1
            while lo < hi and nums[lo] == nums[lo - 1]:
                lo += 1
            while lo < hi and nums[hi] == nums[hi + 1]:
                hi -= 1

if not found:
    print("NONE")

s = input()

last = {}
start = 0
best = 0
for i, ch in enumerate(s):
    if ch in last and last[ch] >= start:
        start = last[ch] + 1        # jump past the earlier copy
    last[ch] = i
    best = max(best, i - start + 1)

print(best)

nums = [int(x) for x in input().split()]
n = len(nums)

q = int(input())
for _ in range(q):
    x = int(input())

    lo, hi = 0, n               # first index with nums[i] >= x
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    first = lo

    lo, hi = 0, n               # first index with nums[i] > x
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] <= x:
            lo = mid + 1
        else:
            hi = mid

    print(lo - first)
